"""
Lab solution: Choosing a Specialisation, Triaging the News, Splitting Weekly Time, Modelling Audience Growth, Writing Quarterly Goals
Standard library only. Ratings and rates are illustrative.
"""
import math
import re

PATHS = {
    "automation specialist": {"needs": {"automation": 3, "business": 2}, "demand": 4},
    "agent engineer": {"needs": {"agents": 4, "coding": 3}, "demand": 5},
    "AI content producer": {"needs": {"tools": 3, "prompting": 3}, "demand": 3},
    "local AI integrator": {"needs": {"coding": 3, "agents": 2, "local": 3}, "demand": 3},
    "AI consultant": {"needs": {"business": 4, "prompting": 3}, "demand": 4},
}
SAM = {"prompting": 4, "tools": 4, "automation": 3, "agents": 2, "coding": 3, "business": 2, "local": 1}
ITEMS = [{"title": "New open model tops benchmark", "topic": "models", "primary": False, "actionable": False, "hype": True},
         {"title": "Ollama release notes: tool-calling fix", "topic": "local tools", "primary": True, "actionable": True, "hype": False},
         {"title": "Automation platform adds AI step", "topic": "automation", "primary": True, "actionable": True, "hype": False},
         {"title": "10 AI side hustles", "topic": "money", "primary": False, "actionable": False, "hype": True},
         {"title": "Survey: small firms adopting AI", "topic": "business", "primary": True, "actionable": False, "hype": False}]
GOALS = [{"result": "Win 3 retainer clients at GBP 432/month", "by": "2027-03-31"},
         {"result": "Learn more about agents", "by": "2027-03-31"},
         {"result": "Publish 12 case-study posts", "by": None}]


# ---------------------------------------------------------------- Step 1
def path_fit(scores, paths=PATHS):
    """Skill gap and demand-weighted fit for each specialisation path."""
    out = []
    for name, p in paths.items():
        gap = sum(max(0, need - scores.get(area, 0)) for area, need in p["needs"].items())
        out.append((name, gap, round(p["demand"] / (1 + gap), 2)))
    return sorted(out, key=lambda x: (-x[2], x[0]))


# ---------------------------------------------------------------- Step 2
def triage(items, interests, limit=5):
    """A weekly digest: relevant, primary, actionable, not hype."""
    keep = []
    for it in items:
        score = (2 if any(k in it["topic"] for k in interests) else 0) + (1 if it["primary"] else 0) \
                + (1 if it["actionable"] else 0) - (2 if it["hype"] else 0)
        if score >= 3:
            keep.append((score, it["title"]))
    keep.sort(key=lambda x: -x[0])
    return [t for _, t in keep[:limit]]


# ---------------------------------------------------------------- Step 3
def time_split(weekly_hours, build=0.7, learn=0.2, news=0.1):
    """Weekly hours for building, learning, and news."""
    return {"build": round(weekly_hours * build, 1), "learn": round(weekly_hours * learn, 1),
            "news": round(weekly_hours * news, 1)}


# ---------------------------------------------------------------- Step 4
def audience(start, monthly_growth, new_per_month, months):
    """Compounding audience growth plus steady additions."""
    a = start
    for _ in range(months):
        a = a * (1 + monthly_growth) + new_per_month
    return round(a)


def enquiries(audience_size, rate):
    """Monthly enquiries from an audience."""
    return math.floor(audience_size * rate)


# ---------------------------------------------------------------- Step 5
def goal_issues(goals):
    """Goals need a number, a date, and a result rather than an activity."""
    out = []
    for g in goals:
        probs = []
        if not re.search(r"\d", g["result"]):
            probs.append("no number")
        if not g.get("by"):
            probs.append("no date")
        if re.search(r"\b(learn|explore|get better|understand)\b", g["result"], re.I):
            probs.append("activity, not result")
        out.append((g["result"], probs))
    return out


if __name__ == "__main__":
    print(path_fit(SAM)[:2])
    print(triage(ITEMS, ["automation", "local", "business"]))
    print(time_split(7))
    print(audience(100, 0.05, 20, 12), enquiries(498, 0.01))
    print(goal_issues(GOALS))
